function races(array $jobs):array{$barrier=dirname(__DIR__,2).'/.local-setup/purchase-race-'.qk();$processes=[];foreach($jobs as $i=>$j){$p=proc_open([PHP_BINARY,__DIR__.'/purchase_worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode($j+['barrier'=>$barrier,'worker'=>$i]));fclose($pipes[0]);$processes[]=[$p,$pipes];}$limit=microtime(true)+15;while(!is_file($barrier.'.ready0')||!is_file($barrier.'.ready1')){if(microtime(true)>$limit)throw new RuntimeException('Barrier timeout');usleep(10000);}file_put_contents($barrier.'.go','go');$out=[];foreach($processes as [$p,$pipes]){$v=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0||$err)throw new RuntimeException('Worker failed');$out[]=json_decode($v,true,512,JSON_THROW_ON_ERROR);}foreach(['.ready0','.ready1','.go'] as $suffix)unlink($barrier.$suffix);return $out;}
