[$id,$clerk]=seed(false);$v=qv($id,$clerk);$out=races([job($clerk,'commit',$v+['amount'=>'100.00','committed_at'=>str_replace(' ','T',$clock),'confirmed'=>'1']),job($clerk,'amend',$v+['limit'=>'120.00','reason'=>'Changed scope'])]);qa(count(array_filter($out,fn($x)=>$x['ok']))===1&&in_array($p->detail($owner,$id)['status'],['committed','change'],true),'Commitment versus revised approval preserves one valid state');
