$out=races([job($owner,'week_decide',['start'=>$start,'outcome'=>'clean','complete'=>'1','evidence'=>'Synthetic prior week','review_token'=>$f->weeklyReview($start)['token']],'finance',null,$monday.' 20:00:00'),job($clerk,'receive',qv($id,$clerk)+['actual_cost'=>'100.00','delivered_at'=>$sunday.'T20:00:00','description'=>'Actual goods received','missing_evidence'=>'Synthetic delivery evidence','received'=>'1'])]);$locked=$f->periodLocked($start);$p=new PurchaseService($a,$monday.' 20:00:00');$p->execute($owner,'post',qv($id,$owner)+['verified'=>'1','reason'=>'Actual source checked in the open period'],qk());$c=$p->detail($owner,$id);$date=$r->run('SELECT expense_date FROM expenses WHERE id=?',[$c['expense_id']])->fetchColumn();qa($out[1]['ok']&&$date===($locked?$monday:$sunday)&&$f->summary($start,$sunday)['expenses']===($locked?$beforeWeek:$beforeWeek+10000),'Week close versus delivery preserves closed totals and one correctly dated cost');
